entries[44933] = { ["name"] = "Muster: Windreißergamaschen", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Lederverarbeitung (440)\nBenutzen: Lehrt Euch die Herstellung von Windreißergamaschen.\n\nWindreißergamaschen\nWird beim Anlegen gebunden\nBeine Leder\n965 Rüstung\n+131 Ausdauer\n+90 Intelligenz\nErhöht Eure kritische Trefferwertung um + 89.\nHaltbarkeit 120 / 120\nBenötigt Stufe 80\nVerkaufspreis:\nBenötigt Schweres boreanisches Leder (12), Äonenluft (6), Äonenwasser (6), Gefrorene Kugel" }
entries[44934] = { ["name"] = "Fingerreif der Kirin Tor", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+75 Ausdauer\n+50 Intelligenz\n+48 Willenskraft\nBenötigt Stufe 80\nBenutzen: Teleportiert den Zaubernden nach Dalaran. (30 Min Abklingzeit)\nVerkaufspreis:" }
entries[44935] = { ["name"] = "Ring der Kirin Tor", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+50 Stärke\n+75 Ausdauer\nErhöht Eure kritische Trefferwertung um + 34.\nErhöht Eure Waffenkundewertung um + 31.\nBenötigt Stufe 80\nBenutzen: Teleportiert den Zaubernden nach Dalaran. (30 Min Abklingzeit)\nVerkaufspreis:" }
entries[44936] = { ["name"] = "Titanbeschlag", ["text"] = "Benötigt Stufe 70\nBenutzen: Bringt dauerhaft einen leichten Titanbeschlag an einem Schild an, der Parieren um 26 erhöht und die Dauer von Entwaffnungseffekten um 50% verringert. Ist nicht mit ähnlichen Effekten stapelbar.\n\nDurch das Anbringen des Titanbeschlags wird Euer Schild seelengebunden.\nVerkaufspreis:" }
entries[44937] = { ["name"] = "Pläne: Titanbeschlag", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Schmiedekunst (450)\nBenötigt Vorposten der Allianz\n- Ehrfürchtig\nBenutzen: Lehrt Euch die Herstellung einer Titanpanzerung.\n\nTitanbeschlag\nBenötigt Stufe 70\nBenutzen: Bringt dauerhaft einen leichten Titanbeschlag an einem Schild an, der Parieren um 26 erhöht und die Dauer von Entwaffnungseffekten um 50% verringert. Ist nicht mit ähnlichen Effekten stapelbar.\n\nDurch das Anbringen des Titanbeschlags wird Euer Schild seelengebunden.\nVerkaufspreis:\nBenötigt Titanbarren (4), Äonenschatten (4)" }
entries[44938] = { ["name"] = "Pläne: Titanbeschlag", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Schmiedekunst (450)\nBenötigt Expedition der Horde\n- Ehrfürchtig\nBenutzen: Lehrt Euch die Herstellung einer Titanpanzerung.\n\nTitanbeschlag\nBenötigt Stufe 70\nBenutzen: Bringt dauerhaft einen leichten Titanbeschlag an einem Schild an, der Parieren um 26 erhöht und die Dauer von Entwaffnungseffekten um 50% verringert. Ist nicht mit ähnlichen Effekten stapelbar.\n\nDurch das Anbringen des Titanbeschlags wird Euer Schild seelengebunden.\nVerkaufspreis:\nBenötigt Titanbarren (4), Äonenschatten (4)" }
entries[44939] = { ["name"] = "Geringes Fläschchen des Widerstands", ["text"] = "Benötigt Stufe 70\nVerkaufspreis:" }
entries[44940] = { ["name"] = "Mit Mais paniertes Würstchen", ["text"] = "Benötigt Stufe 75\nBenutzen: Stellt im Verlauf von 30 Sek. insgesamt 22502 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\n\"... am Stiel!\"\nVerkaufspreis:" }
entries[44941] = { ["name"] = "Frisch gepresstes Limonenwasser", ["text"] = "Benötigt Stufe 70\nBenutzen: Stellt im Verlauf von 30 Sek. insgesamt ( 2140 / 5 * 30) Mana wieder her. Ihr müsst beim Trinken sitzen bleiben.\nVerkaufspreis:" }
