entries[44943] = { ["name"] = "Eisiges Prisma", ["text"] = "Einzigartig\n\"Darin verstecken sich mehrere bezaubernde Edelsteine...\"\n<Zum Öffnen rechtsklicken>" }
entries[44944] = { ["name"] = "Formel: Armschiene - Erhebliche Ausdauer", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (450)\nBenutzen: Lehrt Euch40 Armschienen dauerhaft zu verzaubern40 sodass die Ausdauer um 40 erhöht wird. Erfordert einen Gegenstand der Stufe 40 oder höher.\nArmschienen dauerhaft verzaubern, sodass die Ausdauer um 40 erhöht wird." }
entries[44945] = { ["name"] = "Formel: Waffe - Titanwache", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (450)\nBenutzen: Lehrt Euch50 Nahkampfwaffen dauerhaft zu verzaubern50 sodass die Ausdauer um 50 erhöht wird. Erfordert einen Gegenstand der Stufe 50 oder höher.\nEine Nahkampfwaffe dauerhaft verzaubern, sodass die Ausdauer um 50 erhöht wird." }
entries[44946] = { ["name"] = "Waffe - Titanwache", ["text"] = "Benutzen: Eine Nahkampfwaffe dauerhaft verzaubern, sodass die Ausdauer um 50 erhöht wird.\nVerkaufspreis:" }
entries[44947] = { ["name"] = "Armschiene - Erhebliche Ausdauer", ["text"] = "Benutzen: Armschienen dauerhaft verzaubern, sodass die Ausdauer um 40 erhöht wird.\nVerkaufspreis:" }
entries[44948] = { ["name"] = "Titanstahlverteidiger", ["text"] = "Wird beim Anlegen gebunden\nZweihändig Axt\n819 - 1,229 Schaden Tempo 3.40\n(301.18 Schaden pro Sekunde)\n+89 Stärke\n+133 Ausdauer\n+ 90 Ausweichen\nHaltbarkeit 120 / 120\nBenötigt Stufe 80\nVerkaufspreis:" }
entries[44949] = { ["name"] = "Unzerstörbare Heilungsverstärker", ["text"] = "Wird beim Aufheben gebunden\nKopf Platte\n1901 Rüstung\n+109 Ausdauer\n+74 Intelligenz\nErhöht Eure kritische Trefferwertung um + 73.\n\nMetasockel\nGelber Sockel\nSockelbonus: + 9 Zaubermacht\n\nHaltbarkeit 100 / 100\nBenötigt Stufe 72\nBenötigt Ingenieurskunst (400)\nBenutzen: Ermöglicht Euch, in weite Entfernungen zu sehen. (3 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[44950] = { ["name"] = "Raelorasz' Funken", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Zündet ein Signalfeuer an, das Keristrasza an Euren Standort beschwört. (2 Sek. Abklingzeit)" }
entries[44951] = { ["name"] = "Kiste voller Bomben", ["text"] = "\"Beinhaltet Saronitbomben. Jede Menge Saronitbomben.\"\n<Zum Öffnen rechtsklicken>" }
entries[44953] = { ["name"] = "Worgtatar", ["text"] = "Benötigt Stufe 70\nBenutzen: Stellt im Verlauf von 30 Sek. 22502 Gesundheit und ( 3200 / 5 * 30) Mana wieder her. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 40 Trefferwert und 40 Ausdauer.\nVerkaufspreis:" }
entries[44954] = { ["name"] = "Rezept: Worgtatar", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Kochkunst (400)\nBenutzen: Lehrt Euch, wie man Worgfleisch zu Worgtatar zerkleinert.\nDiese Delikatesse wird am besten roh serviert und benötigt deshalb keine Kochstelle.\n\nWorgtatar\nBenötigt Stufe 70\nBenutzen: Stellt im Verlauf von 30 Sek. 22502 Gesundheit und ( 3200 / 5 * 30) Mana wieder her. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 40 Trefferwert und 40 Ausdauer.\nVerkaufspreis:\nBenötigt Worgschenkel (2), Nordische Gewürze" }
entries[44955] = { ["name"] = "Glyphe 'Arkane Macht'", ["text"] = "Erhebliche Glyphe\nKlassen: Magier\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die Wirkungsdauer und die Abklingzeit von 'Arkane Macht' um 100%.\nVerkaufspreis:" }
entries[44956] = { ["name"] = "Elementium - Das Handbuch für den Goblin", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Bergbau (300)\nBenutzen: Lehrt Euch, wie man Elementium verhüttet.\nVerkaufspreis:\nVerzauberter Elementiumbarren\nVerkaufspreis:\nBenötigt Elementiumblock , Arkanitbarren (10), Feuerkern , Elementarfluxus (3)" }
entries[44957] = { ["name"] = "Große Inschrift des Gladiators", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 70\nBenutzen: Fügt einem Gegenstand für den Schulterplatz dauerhaft 30 Ausdauer und 0 PvP-Abhärtung hinzu.\n\nDurch diese Verzauberung wird der Gegenstand seelengebunden." }
