entries[45725] = { ["name"] = "Argentumhippogryph", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 70\nBenötigt Gekonntes Reiten\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört einen reitbaren Argentumhippogryph oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an." }
entries[45731] = { ["name"] = "Glyphe 'Einlullender Schuss'", ["text"] = "Erhebliche Glyphe\nKlassen: Jäger\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Einlullender Schuss' kostet keinen Fokus mehr, hat jedoch eine Abklingzeit von 10 Sek.\nVerkaufspreis:" }
entries[45732] = { ["name"] = "Glyphe 'Aspekt des Geparden'", ["text"] = "Geringe Glyphe\nKlassen: Jäger\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nIst Eure Fähigkeit 'Aspekt des Geparden' aktiv, werdet Ihr nicht mehr benommen, wenn Ihr getroffen werdet. Stattdessen wird der Effekt abgebrochen und alle Eure Aspekte werden mit einer Abklingzeit von 4 Sek. belegt.\nVerkaufspreis:" }
entries[45733] = { ["name"] = "Glyphe 'Ruf des Meisters'", ["text"] = "Erhebliche Glyphe\nKlassen: Jäger\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die Dauer Eurer Fähigkeit 'Ruf des Meisters' um 4 Sek.\nVerkaufspreis:" }
entries[45734] = { ["name"] = "Glyphe 'Streuschuss'", ["text"] = "Erhebliche Glyphe\nKlassen: Jäger\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die Reichweite der Fähigkeit 'Streuschuss' um 3 Meter.\nVerkaufspreis:" }
entries[45735] = { ["name"] = "Glyphe 'Spiegelnde Klingen'", ["text"] = "Erhebliche Glyphe\nKlassen: Jäger\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn Ihr einen Zaubertreffer erleidet, während 'Abschreckung' aktiv ist, besteht eine Chance von 100%, dass der Zauber auf den Zaubernden reflektiert wird.\nVerkaufspreis:" }
entries[45736] = { ["name"] = "Glyphe 'Wasserelementar'", ["text"] = "Erhebliche Glyphe\nKlassen: Magier\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die Gesundheit Eures Wasserelementars um 40% und ermöglicht es ihm, Zauber während der Bewegung zu wirken. Im Hilfsmodus im Kampf bewirkt der Befehl 'Folgen', dass er in Eurer Nähe bleibt und automatisch 'Wasserblitz' wirkt, wenn ein Ziel in Reichweite gelangt.\nVerkaufspreis:" }
entries[45737] = { ["name"] = "Glyphe 'Verlangsamen'", ["text"] = "Erhebliche Glyphe\nKlassen: Magier\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Arkanschlag' belegt ein beliebiges Ziel, dem er Schaden zufügt, mit dem Effekt Eures Zaubers 'Verlangsamen', soweit zu diesem Zeitpunkt kein anderes Ziel mit Eurem Zauber 'Verlangsamen' belegt ist.\nVerkaufspreis:" }
entries[45738] = { ["name"] = "Glyphe 'Illusion'", ["text"] = "Geringe Glyphe\nKlassen: Magier\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nLehrt Euch die Fähigkeit 'Illusion'.\n\nLässt Euch 2 Min. lang das Aussehen von jemand anderem annehmen.\nVerkaufspreis:" }
entries[45739] = { ["name"] = "Glyphe 'Spiegelbild'", ["text"] = "Geringe Glyphe\nKlassen: Magier\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Spiegelbilder wirken, abhängig von Eurem primären Talentbaum, 'Arkanschlag' oder 'Feuerball' statt 'Frostblitz'.\nVerkaufspreis:" }
entries[45740] = { ["name"] = "Glyphe 'Tieffrieren'", ["text"] = "Erhebliche Glyphe\nKlassen: Magier\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Tieffrieren' ist nicht mehr von globaler Abklingzeit betroffen, allerdings wird seine Dauer um 1 Sek. verringert.\nVerkaufspreis:" }
entries[45741] = { ["name"] = "Glyphe 'Flamme des Glaubens'", ["text"] = "Erhebliche Glyphe\nKlassen: Paladin\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEntfernt die globale Abklingzeit von 'Flamme des Glaubens'.\nVerkaufspreis:" }
entries[45742] = { ["name"] = "Glyphe 'Hammer der Rechtschaffenen'", ["text"] = "Erhebliche Glyphe\nKlassen: Paladin\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nDer körperliche Schadensverringerungseffekt Eurer Fähigkeit 'Hammer der Rechtschaffenen' hält nun 50% länger an.\nVerkaufspreis:" }
entries[45743] = { ["name"] = "Glyphe 'Göttlicher Sturm'", ["text"] = "Erhebliche Glyphe\nKlassen: Paladin\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Göttlicher Sturm' heilt Euch um 5% Eurer maximalen Gesundheit.\nVerkaufspreis:" }
entries[45744] = { ["name"] = "Glyphe 'Alabasterschild'", ["text"] = "Erhebliche Glyphe\nKlassen: Paladin\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErfolgreiches Blocken erhöht den Schaden Eures nächsten Einsatzes von 'Schild der Rechtschaffenen' um 10%. Bis zu 3-mal stapelbar.\nVerkaufspreis:" }
entries[45745] = { ["name"] = "Glyphe 'Göttliche Bitte'", ["text"] = "Erhebliche Glyphe\nKlassen: Paladin\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\n'Göttliche Bitte' stellt 50% weniger Mana wieder her, dafür ist die Abklingzeit 50% kürzer.\nVerkaufspreis:" }
entries[45746] = { ["name"] = "Glyphe 'Heiliger Schock'", ["text"] = "Erhebliche Glyphe\nKlassen: Paladin\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nVerringert die gewirkte Heilung Eures Zaubers 'Heiliger Schock' um 50%, erhöht jedoch seinen verursachten Schaden um 50%.\nVerkaufspreis:" }
entries[45747] = { ["name"] = "Glyphe 'Inquisition'", ["text"] = "Erhebliche Glyphe\nKlassen: Paladin\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die Effektdauer von 'Inquisition' um 30 Sek., wenn Ihr einem Gegner den Todesstoß versetzt, der Erfahrung oder Ehre gewährt.\nVerkaufspreis:" }
entries[45753] = { ["name"] = "Glyphe 'Dispersion'", ["text"] = "Erhebliche Glyphe\nKlassen: Priester\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nVerringert die Abklingzeit Eures Zaubers 'Dispersion' um 15 Sek.\nVerkaufspreis:" }
entries[45755] = { ["name"] = "Glyphe 'Glaubenssprung'", ["text"] = "Erhebliche Glyphe\nKlassen: Priester\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Glaubenssprung' entfernt nun alle bestehenden bewegungeinschränkenden Effekte vom Ziel.\nVerkaufspreis:" }
entries[45756] = { ["name"] = "Glyphe 'Sühne'", ["text"] = "Erhebliche Glyphe\nKlassen: Priester\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die Manakosten von 'Sühne' um 20%, Ihr könnt den Zauber jedoch während des Laufens wirken.\nVerkaufspreis:" }
entries[45757] = { ["name"] = "Glyphe 'Gebündelte Besserung'", ["text"] = "Erhebliche Glyphe\nKlassen: Priester\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\n'Gebet der Besserung' springt nur noch zwischem dem Ziel und dem Zaubernden hin und her.\nVerkaufspreis:" }
entries[45758] = { ["name"] = "Glyphe 'Gedankenstachel'", ["text"] = "Erhebliche Glyphe\nKlassen: Priester\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErfolgreiches Wirken von 'Gedankenstachel' mit Zauberzeit verringert die Zauberzeit Eures nächsten Wirkens von 'Gedankenschlag' innerhalb von 9 Sek. um 50%. Dieser Effekt ist bis zu 2-mal stapelbar.\nVerkaufspreis:" }
entries[45760] = { ["name"] = "Glyphe 'Verbindende Heilung'", ["text"] = "Erhebliche Glyphe\nKlassen: Priester\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Verbindende Heilung' heilt nun ein drittes Ziel innerhalb von 20 Metern, die Manakosten werden jedoch um 35% erhöht.\nVerkaufspreis:" }
entries[45761] = { ["name"] = "Glyphe 'Vendetta'", ["text"] = "Erhebliche Glyphe\nKlassen: Schurke\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nVerringert den Schadensbonus Eurer Fähigkeit 'Vendetta' um 5%, erhöht jedoch ihre Dauer um 10 Sek.\nVerkaufspreis:" }
entries[45762] = { ["name"] = "Glyphe 'Mordlust'", ["text"] = "Geringe Glyphe\nKlassen: Schurke\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn der Effekt Eurer Fähigkeit 'Mordlust' endet, werdet Ihr an Euren Anfangspunkt zurückversetzt.\nVerkaufspreis:" }
entries[45764] = { ["name"] = "Glyphe 'Verstohlenheit'", ["text"] = "Erhebliche Glyphe\nKlassen: Schurke\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nVerringert die Abklingzeit Eurer Fähigkeit 'Verstohlenheit' um 4 Sek.\nVerkaufspreis:" }
entries[45765] = { ["name"] = "Schwarze Kavallerieklinge", ["text"] = "Eiskrone\nWird beim Aufheben gebunden\nEinzigartig\nWaffenhand\n4 - 8 Schaden Tempo 3.00\n(2.00 Schaden pro Sekunde)\nHaltbarkeit 16 / 16\nBenötigt Stufe 77" }
entries[45766] = { ["name"] = "Glyphe 'Tödliche Dynamik'", ["text"] = "Erhebliche Glyphe\nKlassen: Schurke\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn Ihr ein Ziel tötet, das Erfahrung oder Ehre gewährt, wird die laufende Effektdauer Eurer Fähigkeiten 'Zerhäckseln' und 'Gesundung' zurückgesetzt.\nVerkaufspreis:" }
entries[45767] = { ["name"] = "Glyphe 'Schurkenhandel'", ["text"] = "Geringe Glyphe\nKlassen: Schurke\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nVerringert die Energiekosten Eurer Fähigkeit 'Schurkenhandel' um 100%, dem Ziel wird jedoch kein Schadensbonus mehr gewährt.\nVerkaufspreis:" }
entries[45768] = { ["name"] = "Glyphe 'Verkleiden'", ["text"] = "Geringe Glyphe\nKlassen: Schurke\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn Ihr einen humanoiden Gegner bestehlt, kopiert Ihr 5 Min. lang sein Erscheinungsbild. Eure Verkleidung schwindet, sobald Ihr den Kampf beginnt.\nVerkaufspreis:" }
entries[45769] = { ["name"] = "Glyphe 'Mantel der Schatten'", ["text"] = "Erhebliche Glyphe\nKlassen: Schurke\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWährend die Fähigkeit 'Mantel der Schatten' aktiv ist, erleidet Ihr 40% weniger körperlichen Schaden.\nVerkaufspreis:" }
entries[45770] = { ["name"] = "Glyphe 'Donner'", ["text"] = "Erhebliche Glyphe\nKlassen: Schamane\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nVerringert die Abklingzeit Eures Zaubers 'Gewitter' um 10 Sek.\nVerkaufspreis:" }
entries[45771] = { ["name"] = "Glyphe 'Wildgeist'", ["text"] = "Erhebliche Glyphe\nKlassen: Schamane\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die Heilung der Fähigkeit 'Geisterjagd' Eurer Wildgeister um 40%.\nVerkaufspreis:" }
entries[45772] = { ["name"] = "Glyphe 'Springflut'", ["text"] = "Erhebliche Glyphe\nKlassen: Schamane\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEntfernt die Abklingzeit Eures Zaubers 'Springflut', verringert aber die direkte Initialheilung um 75%.\nVerkaufspreis:" }
entries[45773] = { ["name"] = "Smaragdtasche", ["text"] = "Wird beim Anlegen gebunden\n32 Platz Kräutertasche\nVerkaufspreis:" }
entries[45774] = { ["name"] = "Muster: Smaragdtasche", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Schneiderei (435)\nBenötigt Die Kalu'ak\n- Respektvoll\nBenutzen: Lehrt Euch, wie man eine Smaragdtasche näht.\nVerkaufspreis:\nSmaragdtasche\nWird beim Anlegen gebunden\n32 Platz Kräutertasche\nVerkaufspreis:\nBenötigt Mondgespinst (4), Frostlotus (6)" }
entries[45775] = { ["name"] = "Glyphe 'Regenguss'", ["text"] = "Geringe Glyphe\nKlassen: Schamane\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Kettenheilung' hat nun das Erscheinungsbild von Wasser.\nVerkaufspreis:" }
entries[45776] = { ["name"] = "Glyphe 'Schamanistische Wut'", ["text"] = "Erhebliche Glyphe\nKlassen: Schamane\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn Ihr Eure Fähigkeit 'Schamanistische Wut' aktiviert, werden gleichzeitig alle bannbaren magischen Schwächungseffekte entfernt.\nVerkaufspreis:" }
entries[45777] = { ["name"] = "Glyphe 'Verhexen'", ["text"] = "Erhebliche Glyphe\nKlassen: Schamane\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nVerringert die Abklingzeit Eures Zaubers 'Verhexen' um 10 Sek.\nVerkaufspreis:" }
entries[45778] = { ["name"] = "Glyphe 'Totemische Lebenskraft'", ["text"] = "Erhebliche Glyphe\nKlassen: Schamane\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die Gesundheit Eurer Totems um 5% Eurer maximalen Gesundheit.\nVerkaufspreis:" }
entries[45779] = { ["name"] = "Glyphe 'Blutsauger'", ["text"] = "Erhebliche Glyphe\nKlassen: Hexenmeister\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die durch Euren Zauber 'Blutsauger' erzeugte Heilung um 30%.\nVerkaufspreis:" }
entries[45780] = { ["name"] = "Glyphe 'Dämonenjagd'", ["text"] = "Erhebliche Glyphe\nKlassen: Hexenmeister\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nBenötigt Dämonologie.\n\nLehrt Euch den Zauber ' Dunkle Apotheose '.\n\nDunkle Apotheose\nDurchtränkt Euch mit dämonischen Energien, die Euren erlittenen körperlichen Schaden um 13.85% und den erlittenen Magieschaden um 15% verringern sowie den Einsatz verschiedener Dämonenfähigkeiten gestatten.\n\nZusätzlich wird Euer Zauber 'Seele brechen' zu 'Provokation', der Euer Ziel verspottet. Außerdem wird Euer Zauber 'Zwielichtzauberschutz' zu 'Zornbarriere', der alle Zauberarten absorbiert, Euer Zauber 'Schattenblitz' wird zu 'Dämonischer Hieb' und Euer Zauber 'Furcht' wird zu 'Schlaf'.\nVerkaufspreis:" }
entries[45781] = { ["name"] = "Glyphe 'Funkenwandlung'", ["text"] = "Erhebliche Glyphe\nKlassen: Hexenmeister\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die durch Euren Zauber 'Funkenwandlung' erzeugte Heilung um zusätzlich 5% Eurer Gesundheit, die Gesundheit wird jedoch über einen Zeitraum von 10 Sek. regeneriert.\nVerkaufspreis:" }
entries[45782] = { ["name"] = "Glyphe 'Dämonischer Zirkel'", ["text"] = "Erhebliche Glyphe\nKlassen: Hexenmeister\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nVerringert die Abklingzeit Eures Zaubers 'Dämonischer Zirkel' um 4 Sek.\nVerkaufspreis:" }
entries[45783] = { ["name"] = "Glyphe 'Erbarmungslose Entschlossenheit'", ["text"] = "Erhebliche Glyphe\nKlassen: Hexenmeister\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nDie Schadensverringerung Eures Zaubers 'Erbarmungslose Entschlossenheit' wird um 20% verringert, die Abklingzeit wird um 60 Sek. verringert.\nVerkaufspreis:" }
