entries[45793] = { ["name"] = "Glyphe 'Siegeswurf'", ["text"] = "Erhebliche Glyphe\nKlassen: Krieger\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die Reichweite Eurer Fähigkeiten 'Siegesrausch' und 'Bevorstehender Sieg' um 15 Meter.\nVerkaufspreis:" }
entries[45794] = { ["name"] = "Glyphe 'Drohruf'", ["text"] = "Geringe Glyphe\nKlassen: Krieger\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nDie Ziele Eurer Fähigkeit 'Drohruf' fliehen nun nicht mehr, sondern erzittern vor Furcht.\nVerkaufspreis:" }
