entries[45801] = { ["name"] = "Zügel des eisenbeschlagenen Protodrachen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 70\nBenötigt Gekonntes Reiten\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört einen reitbaren eisenbeschlagenen Protodrachen oder gibt ihn wieder frei. Das ist ein Flugreittier." }
