entries[45804] = { ["name"] = "Glyphe 'Todesmantel'", ["text"] = "Erhebliche Glyphe\nKlassen: Todesritter\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Todesmantel' kann nun auf alle Verbündeten gewirkt werden. Wenn der Zauber einen nicht-untoten Verbündeten trifft, hüllt 'Todesmantel' ihn in eine schützende Barriere, die bis zu [( 75 + 0.514 * Angriffskraft) * 1 ] Schaden absorbiert.\nVerkaufspreis:" }
